import { useEffect, useState } from "react";

/* ------------------------------------------------------------------ */
/* Destination tracker — the ONE trending ordering.                   */
/*                                                                    */
/* Data: public/data/travel-destinations.json (generated by           */
/* pipeline/build-travel-destinations.py). Its `trending_now` array   */
/* is the generator's deterministic ranking over pick-eligible        */
/* destinations. Since the 2026-10-15 real-signal flip (Kiran:        */
/* "Flip to real trending now, with those conditions") the score is   */
/* season 40 / search interest 30 / fare 20 / value 10 — search        */
/* interest is Wikimedia attention level + momentum today, Google     */
/* Trends when its token lands — with ties broken by fare data,       */
/* search data, then search level/momentum; name is the last resort   */
/* only. (Pre-flip weights were so flat the ranking degenerated to    */
/* a 23-way tie broken alphabetically; the builder still emits the    */
/* legacy ranking to its review artifact for the Nov 9 checkpoint.)   */
/*                                                                    */
/* Both surfaces that render this ranking — the /travel rail          */
/* (TrendingDestinations) and the Your Hub strip (HubTrendingStrip)   */
/* — MUST select their cards through selectTrendingCards /            */
/* useTrendingDestinations in this module, never through a local      */
/* copy of the logic. That is what guarantees rank integrity: a card's */
/* badge is its 1-based position in this single ordered list, the Hub */
/* shows its first 5 and /travel its first 8 — always a strict        */
/* prefix, so the two surfaces can never disagree. (2026-10-15: the    */
/* two screenshots Kiran compared actually straddled a data rebuild   */
/* that re-ranked the list — Karnataka #1 in one build, Australia #1  */
/* in the next — but the duplicated selection logic in two components */
/* was an accident waiting to fork for real.)                         */
/*                                                                    */
/* Tiering (Kiran, 2026-10-14): USA-group destinations are eligible   */
/* only if top-tier (Hawaii, Alaska, Yellowstone/national-parks).     */
/* The dataset's eligible_for_picks flag is authoritative; the slug   */
/* allowlist is the belt-and-braces fallback. International + India   */
/* are all eligible.                                                  */
/* ------------------------------------------------------------------ */

export const TOP_TIER_USA = new Set(["hawaii", "alaska", "national-parks"]);

export type TrendingComponent = {
  id: string;
  points: number | null;
  max: number;
  reason: string;
};

export type FareFrom = {
  price_min: number;
  route: string;
  origin_metro: string;
  dest_metro: string;
  date_range: string;
  /** Band model (2026-10-15): actual trip length of the fare. */
  duration_days?: number;
  /** Legacy pre-band field. */
  weeks?: number;
  as_of: string;
  /** "daily" (India matrix) | "weekly" (intl matrix, indicative). */
  cadence?: string;
  indicative?: boolean;
} | null;

export type TrendingDestination = {
  slug: string;
  name: string;
  guide_url: string;
  group: "india" | "usa" | "international";
  region: string;
  best_months: number[];
  season_note: string;
  hero_image: string | null;
  fare_from: FareFrom;
  highlights: { title: string; snippet: string }[];
  trending: {
    score: number;
    max_score: number;
    components: TrendingComponent[];
  };
  eligible_for_picks?: boolean;
};

export type DestinationsData = {
  generated_at: string;
  current_month: number;
  current_year: number;
  trending_now: string[];
  destinations: TrendingDestination[];
  /** India country card for the /travel rail (Kiran, 2026-10-15).
      Emitted separately by the builder (build_india_card): NOT a
      destination record, NOT in trending_now, carries NO rank. The
      /travel rail renders it FIRST (editorial placement, Kiran
      2026-10-15 20:38) with no badge — first slot is not a rank;
      ranked cards keep their ranking-numbered badges. It links to
      /travel/india, India's own destination page. The Hub strip
      does not render it. Null when no India data exists. */
  india_card?: TrendingDestination | null;
};

export type GalleryData = Record<
  string,
  { photos: { src: string; caption: string }[] }
>;

let destCache: Promise<DestinationsData | null> | null = null;
export function loadDestinations(): Promise<DestinationsData | null> {
  if (!destCache) {
    destCache = fetch("/data/travel-destinations.json")
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return destCache;
}

let galleryCache: Promise<GalleryData | null> | null = null;
export function loadGalleries(): Promise<GalleryData | null> {
  if (!galleryCache) {
    galleryCache = fetch("/data/travel-galleries.json")
      .then((r) => (r.ok ? r.json() : null))
      .catch(() => null);
  }
  return galleryCache;
}

export function isEligible(d: TrendingDestination): boolean {
  if (typeof d.eligible_for_picks === "boolean") return d.eligible_for_picks;
  if (d.group === "usa") return TOP_TIER_USA.has(d.slug);
  return true;
}

/** The single ordered, eligible card list for a surface. `limit` only
    truncates the tail — position i in the result is rank i+1 everywhere. */
export function selectTrendingCards(
  data: DestinationsData | null,
  limit: number,
): TrendingDestination[] {
  if (!data) return [];
  const bySlug = new Map(data.destinations.map((d) => [d.slug, d]));
  return data.trending_now
    .map((slug) => bySlug.get(slug))
    .filter((d): d is TrendingDestination => !!d && isEligible(d))
    .slice(0, limit);
}

/** Shared loader hook: tracker data + galleries + the ordered cards. */
export function useTrendingDestinations(limit: number): {
  data: DestinationsData | null;
  galleries: GalleryData | null;
  cards: TrendingDestination[];
} {
  const [data, setData] = useState<DestinationsData | null>(null);
  const [galleries, setGalleries] = useState<GalleryData | null>(null);

  useEffect(() => {
    let alive = true;
    loadDestinations().then((d) => {
      if (alive) setData(d);
    });
    loadGalleries().then((g) => {
      if (alive) setGalleries(g);
    });
    return () => {
      alive = false;
    };
  }, []);

  return { data, galleries, cards: selectTrendingCards(data, limit) };
}
